query CategoryByPath($path: String!) {
  site {
    route(path: $path) {
      redirect {
        toUrl
      }
      node {
        __typename
        ... on Category {
          entityId
          name
          path
          description
          defaultImage {
            url(width: 640)
            altText
          }
          breadcrumbs(depth: 5) {
            edges {
              node {
                entityId
                name
                path
              }
            }
          }
          seo {
            pageTitle
            metaDescription
            metaKeywords
          }
          products(first: 10) {
            collectionInfo {
              totalItems
            }
            pageInfo {
              hasNextPage
              endCursor
            }
            edges {
              node {
                entityId
                name
                path
                defaultImage {
                  url(width: 320)
                  altText
                }
                prices {
                  price {
                    value
                    currencyCode
                  }
                  basePrice {
                    value
                    currencyCode
                  }
                  salePrice {
                    value
                    currencyCode
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}
